import React from 'react';
import { BrowserRouter as Router, Routes, Route, useLocation } from 'react-router-dom';
import Navbar from './Components/Navbar/Navbar'; // Your global navigation
import SellerDashboard from './Pages/SellerDashboard'; // Your seller portal
import HomePage from './Pages/Home';
import ProductsPage from './Pages/Products';
import CartPage from './Pages/CartPage';

function LayoutWrapper() {
  const location = useLocation();
  const isSellerRoute = location.pathname.startsWith('/seller');

  return (
    <div style={{ display: 'flex' }}>
      {/* Show global sidebar ONLY if we are NOT on the seller pages */}
      {!isSellerRoute && <Navbar />}

      {/* Main content viewport */}
      <div style={{ flex: 1, marginLeft: isSellerRoute ? '0px' : '250px' }}>
        <Routes>
          {/* Store Routes */}
          <Route path="/" element={<HomePage />} />
          <Route path="/products" element={<ProductsPage />} />
          <Route path="/cart" element={<CartPage />} />

          {/* Seller Portal Routes (Keeps its own layout completely safe!) */}
          <Route path="/seller" element={<SellerDashboard />} />
        </Routes>
      </div>
    </div>
  );
}

function App() {
  return (
    <Router>
      <LayoutWrapper />
    </Router>
  );
}

export default App;
